import XCTest
@testable import ColorComposerCore

/// Replays the `color_matching` solver parity corpus against
/// `WeightedSquaredErrorScorer` so client/server divergence in scores,
/// missing-measurement exclusions, or earliest-wins tie-breaking fails CI.
///
/// The corpus (see `docs/solver-parity-corpus.md`) is the golden-vector
/// contract generated by the Elixir server; every expectation here was
/// computed by `ColorMatching.WeightedSquaredError` +
/// `IlluminantMatching.best_match/3` upstream.
final class WeightedSquaredErrorParityCorpusTests: XCTestCase {
    private let scorer = WeightedSquaredErrorScorer()

    // MARK: - Corpus contract

    func testCorpusMetadataMatchesSolverContract() throws {
        let corpus = try ParityCorpusFixture.load()

        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, LightingCondition.allCases.map(\.rawValue))
        XCTAssertGreaterThanOrEqual(corpus.scenarios.count, 12)
        XCTAssertEqual(Set(corpus.scenarios.map(\.id)).count, corpus.scenarios.count, "scenario ids must be unique")
    }

    func testCorpusRetainsTieCoverage() throws {
        let corpus = try ParityCorpusFixture.load()
        let ids = Set(corpus.scenarios.map(\.id))

        XCTAssertGreaterThanOrEqual(
            corpus.scenarios.filter { $0.expected.tieBroke == true }.count, 3,
            "corpus refresh dropped tie cases; the parity suite must keep exercising exact ties"
        )
        for required in ["tie-symmetric-around-target", "tie-duplicate-vectors",
                         "tie-three-way-on-lps", "zero-weight-channel-missing",
                         "mixed-large-palette"] {
            XCTAssertTrue(ids.contains(required), "corpus is missing scenario \(required)")
        }
    }

    // MARK: - Scorer-level replay (scores, exclusions, selection, ties)

    func testScorerReplaysEveryScenarioExactly() throws {
        let corpus = try ParityCorpusFixture.load()
        for scenario in corpus.scenarios {
            try assertScenarioReplays(scenario)
        }
    }

    func testUnknownWeightKeysAreIgnored() throws {
        let corpus = try ParityCorpusFixture.load()
        let scenario = try XCTUnwrap(corpus.scenario(id: "unknown-weight-ignored"))
        let (weights, ignoredKeys) = mappedWeights(scenario.weights)

        XCTAssertEqual(ignoredKeys, ["ultraviolet"])
        XCTAssertEqual(weights, ChannelWeights(white: 0.5, red: 1.0, green: 1.0, blue: 0.25, lps: 1.5))

        // The corpus pins that ignoring the unknown key reproduces the
        // distinct-errors scenario verbatim; assert that claimed equivalence.
        let baseline = try XCTUnwrap(corpus.scenario(id: "distinct-errors"))
        XCTAssertEqual(scenario.expected.scores.map(\.outcome), baseline.expected.scores.map(\.outcome))
        XCTAssertEqual(scenario.expected.selectedIndex, baseline.expected.selectedIndex)
        XCTAssertEqual(scenario.expected.error, baseline.expected.error)
    }

    // MARK: - Solver-level replay (production selection path, earliest wins)

    func testSolverReplaysCorpusSelections() throws {
        let corpus = try ParityCorpusFixture.load()
        var skipped: [String] = []

        for scenario in corpus.scenarios {
            let (weights, _) = mappedWeights(scenario.weights)
            let active = weights.activeConditions

            // The solver's target always carries a value per active channel
            // (it comes from source grids), so a corpus target that is itself
            // missing a required channel is inexpressible here; those
            // scenarios are covered by the scorer-level replay.
            guard active.allSatisfy({ scenario.target.channels[$0.rawValue] != nil }) else {
                skipped.append(scenario.id)
                continue
            }

            let result = try solve(scenario, weights: weights)
            let expected = scenario.expected

            if let selected = expected.selectedIndex {
                XCTAssertEqual(result.colorIndex(x: 0, y: 0), selected, "solver selection in \(scenario.id)")
                XCTAssertEqual(result.error(x: 0, y: 0), try XCTUnwrap(expected.error), accuracy: 1e-12, "solver error in \(scenario.id)")
            } else {
                XCTAssertNil(result.colorIndex(x: 0, y: 0), "no candidate is scorable in \(scenario.id)")
                XCTAssertTrue(result.error(x: 0, y: 0).isInfinite, "unmatched cell must record infinite error in \(scenario.id)")
            }

            let excluded = expected.scores.filter { $0.outcome == .excluded }.count
            XCTAssertEqual(result.excludedCandidateCount, excluded, "excluded diagnostics in \(scenario.id)")
        }

        XCTAssertEqual(skipped, ["missing-target-excluded"], "only the missing-target scenario is solver-inexpressible")
    }

    // MARK: - Replay helpers

    /// Mirrors `IlluminantMatching.best_match/3`: minimum score, earliest
    /// index wins; `nil` selection when every candidate is excluded.
    private struct CorpusSelection: Equatable {
        let selectedIndex: Int?
        let error: Double?
        let tieBroke: Bool?
        let tiedIndices: [Int]
        let selectedHexColor: String?
    }

    private func selection(
        from outcomes: [(position: Int, value: Double?)],
        paletteHexes: [String]
    ) -> CorpusSelection {
        let scorable = outcomes.compactMap { entry -> (Int, Double)? in
            entry.value.map { (entry.position, $0) }
        }
        guard !scorable.isEmpty else {
            return CorpusSelection(selectedIndex: nil, error: nil, tieBroke: nil, tiedIndices: [], selectedHexColor: nil)
        }

        let minimum = scorable.map { $0.1 }.min()!
        let tied = scorable.filter { $0.1 == minimum }.map { $0.0 }
        let selected = tied.first!
        return CorpusSelection(
            selectedIndex: selected,
            error: minimum,
            tieBroke: tied.count > 1,
            tiedIndices: tied,
            selectedHexColor: paletteHexes[selected]
        )
    }

    private func assertSelection(
        _ actual: CorpusSelection,
        matches expected: ParityCorpus.Expected,
        scenario: String,
        file: StaticString = #filePath,
        line: UInt = #line
    ) throws {
        XCTAssertEqual(actual.selectedIndex, expected.selectedIndex, "selection in \(scenario)", file: file, line: line)
        if let error = actual.error {
            XCTAssertEqual(error, try XCTUnwrap(expected.error), accuracy: 1e-12, "winning error in \(scenario)", file: file, line: line)
        } else {
            XCTAssertNil(expected.error, "expected no scorable candidate in \(scenario)", file: file, line: line)
        }
        XCTAssertEqual(actual.tieBroke, expected.tieBroke, "tie_broke in \(scenario)", file: file, line: line)
        XCTAssertEqual(actual.tiedIndices, expected.tiedIndices, "tied indices in \(scenario)", file: file, line: line)
        XCTAssertEqual(actual.selectedHexColor, expected.selectedHexColor, "winner hex in \(scenario)", file: file, line: line)
    }

    /// Asserts one scenario's per-candidate scores, exclusion markers, and
    /// selection (earliest index wins) against the corpus expectation.
    private func assertScenarioReplays(
        _ scenario: ParityCorpus.Scenario,
        file: StaticString = #filePath,
        line: UInt = #line
    ) throws {
        let (weights, _) = mappedWeights(scenario.weights)
        let target = self.target(from: scenario.target)
        let palette = try scenario.palette.map { try color(from: $0) }
        let expected = scenario.expected

        guard expected.scores.count == palette.count else {
            XCTFail("expected \(palette.count) scores, found \(expected.scores.count) in \(scenario.id)", file: file, line: line)
            return
        }

        var outcomes: [(position: Int, value: Double?)] = []
        for (position, candidate) in palette.enumerated() {
            let actual = scorer.score(candidate: candidate, target: target, weights: weights)
            let expectedScore = expected.scores[position]
            XCTAssertEqual(expectedScore.index, position, "scores must be in palette order", file: file, line: line)

            switch (actual, expectedScore.outcome) {
            case (.excluded, .excluded):
                outcomes.append((position, nil))
            case (.score(let value), .score(let expectedValue)):
                outcomes.append((position, value))
                XCTAssertEqual(value, expectedValue, accuracy: 1e-12, "candidate \(position) score in \(scenario.id)", file: file, line: line)
            case (.score, .excluded):
                XCTFail("candidate \(position) in \(scenario.id): expected excluded, got a score", file: file, line: line)
            case (.excluded, .score(let expectedValue)):
                XCTFail("candidate \(position) in \(scenario.id): expected score \(expectedValue), got excluded", file: file, line: line)
            }
        }

        try assertSelection(
            selection(from: outcomes, paletteHexes: palette.map { $0.hex }),
            matches: expected,
            scenario: scenario.id,
            file: file,
            line: line
        )
    }

    /// Runs one scenario through the production solver on a 1×1 grid whose
    /// cell carries the corpus target vector.
    private func solve(_ scenario: ParityCorpus.Scenario, weights: ChannelWeights) throws -> CompositionResult {
        var grids: [LightingCondition: BrightnessGrid] = [:]
        for condition in weights.activeConditions {
            let value = try XCTUnwrap(scenario.target.channels[condition.rawValue])
            grids[condition] = BrightnessGrid(width: 1, height: 1, fill: value)
        }
        let palette = try scenario.palette.map { try color(from: $0) }
        return try CompositionSolver(scorer: scorer).solve(palette: palette, sourceGrids: grids, weights: weights)
    }

    // MARK: - Corpus → domain mapping

    /// Maps raw corpus weight keys onto `ChannelWeights`; keys outside the
    /// canonical light sources (e.g. `ultraviolet`) are ignored, mirroring the
    /// server's `filter_weights/1`.
    private func mappedWeights(_ raw: [String: Double]) -> (weights: ChannelWeights, ignoredKeys: [String]) {
        var perCondition: [LightingCondition: Double] = [:]
        var ignored: [String] = []
        for (key, value) in raw {
            if let condition = LightingCondition(rawValue: key) {
                perCondition[condition] = value
            } else {
                ignored.append(key)
            }
        }
        let weights = ChannelWeights(
            white: perCondition[.white] ?? 0,
            red: perCondition[.red] ?? 0,
            green: perCondition[.green] ?? 0,
            blue: perCondition[.blue] ?? 0,
            lps: perCondition[.lps] ?? 0
        )
        return (weights, ignored.sorted())
    }

    /// Corpus vectors distinguish *missing* (key absent) from *measured zero*
    /// (key present with value 0), matching `PaletteColor.responses` absence.
    private func color(from vector: ParityCorpus.Vector) throws -> PaletteColor {
        let rgb = try XCTUnwrap(RGBColor(hex: vector.hexColor), "corpus hex must parse: \(vector.hexColor)")
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                responses[condition] = IlluminationResponse(brightness: value)
            }
        }
        return PaletteColor(id: vector.index ?? -1, hex: vector.hexColor, rgb: rgb, responses: responses)
    }

    private func target(from vector: ParityCorpus.Vector) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                brightness[condition] = value
            }
        }
        return TargetResponseVector(brightness)
    }
}
